#include <iostream>
using namespace std;

class FishBowl {
public:
    static FishBowl& getInstance() {
        static FishBowl only;
        return only;
    }
    void add(int n) { count += n; }
    int count = 0;
private:
    FishBowl() = default;
};

int main() {
    FishBowl& a = FishBowl::getInstance();
    a.add({w1});
    FishBowl& b = FishBowl::getInstance();
    b.add({w2});
    cout << "a 的碗：" << a.count << endl;
    cout << "b 的碗：" << b.count << endl;
    cout << "同一只：" << (&a == &b ? "是" : "不是") << endl;
    return 0;
}
